#define MAXN 105
#define MAXM 5005

typedef struct {
    int u, v, a, b;
} Edge;

Edge edges[MAXM];
int parent[MAXN];
int n, m;

int find(int x) {
    if (parent[x] != x)
        parent[x] = find(parent[x]);
    return parent[x];
}

void union_sets(int x, int y) {
    int rx = find(x), ry = find(y);
    if (rx != ry) parent[ry] = rx;
}

int cmp(const void *a, const void *b) {
    Edge *ea = (Edge*)a;
    Edge *eb = (Edge*)b;
    int wa = ea->a, wb = eb->a;
    if (wa != wb) return wb - wa;
    return eb->b - ea->b;
}

int main() {
    int y_start, y_end;
    scanf("%d %d %d %d", &n, &m, &y_start, &y_end);
    for (int i = 0; i < m; i++) {
        scanf("%d %d %d %d", &edges[i].u, &edges[i].v, &edges[i].a, &edges[i].b);
    }

    long long max_bandwidth = LLONG_MIN;

    for (int y = y_start; y <= y_end; y++) {
        // Re-sort edges by weight for year y
        Edge temp_edges[MAXM];
        memcpy(temp_edges, edges, sizeof(Edge) * m);

        // Sort by a*y + b descending using simple bubble sort since m is small
        for (int i = 0; i < m - 1; i++) {
            for (int j = 0; j < m - i - 1; j++) {
                long long w1 = (long long)temp_edges[j].a * y + temp_edges[j].b;
                long long w2 = (long long)temp_edges[j+1].a * y + temp_edges[j+1].b;
                if (w2 > w1) {
                    Edge t = temp_edges[j];
                    temp_edges[j] = temp_edges[j+1];
                    temp_edges[j+1] = t;
                }
            }
        }

        // Kruskal-like maximum spanning tree
        for (int i = 1; i <= n; i++) parent[i] = i;
        long long best = LLONG_MIN;

        for (int i = 0; i < m; i++) {
            int u = temp_edges[i].u, v = temp_edges[i].v;
            if (find(u) != find(v)) {
                union_sets(u, v);
                // Check connectivity from 1 to n
                if (find(1) == find(n)) {
                    long long w = (long long)temp_edges[i].a * y + temp_edges[i].b;
                    best = w;
                    break;
                }
            }
        }

        if (best > max_bandwidth) max_bandwidth = best;
    }

    printf("%lld\n", max_bandwidth);
    return 0;
