// Simple max flow with integer capacities first
#define MAXN 105
#define INF 1000000000

int cap[MAXN][MAXN];
int n, m;
int parent[MAXN];
int visited[MAXN];
int queue[MAXN];

int bfs(int s, int t) {
    memset(visited, 0, sizeof(visited));
    int front = 0, rear = 0;
    queue[rear++] = s;
    visited[s] = 1;
    parent[s] = -1;
    while (front < rear) {
        int u = queue[front++];
        for (int v = 1; v <= n; v++) {
            if (!visited[v] && cap[u][v] > 0) {
                visited[v] = 1;
                parent[v] = u;
                if (v == t) return 1;
                queue[rear++] = v;
            }
        }
    }
    return 0;
}

int maxflow(int s, int t) {
    int flow = 0;
    while (bfs(s, t)) {
        int path_flow = INF;
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            if (cap[u][v] < path_flow) path_flow = cap[u][v];
        }
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            cap[u][v] -= path_flow;
            cap[v][u] += path_flow;
        }
        flow += path_flow;
    }
    return flow;
}

int main() {
