        cap[u][v] += w;
        cap[v][u] += w;
    }
    printf("%d\n", maxflow(1, n));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 205
#define MAXM 40005
#define MAXDEG 25
#define INF 1e100

typedef struct {
    int to, next;
    int coeff[MAXDEG + 1];
} Edge;

static Edge edges[MAXM * 2];
static int head[MAXN];
static int ecnt = 0;

static int n, m, k, year_q;

static void add_edge(int u, int v, int *c) {
    edges[ecnt].to = v;
    memcpy(edges[ecnt].coeff, c, sizeof(int) * (k + 1));
    edges[ecnt].next = head[u];
    head[u] = ecnt++;
}

static double eval_poly(int *c, int deg, int x) {
    double res = 0.0;
    for (int i = deg; i >= 0; --i) {
        res = res * x + c[i];
    }
    return res;
}

static double best[MAXN];
static int used[MAXN];

int main(void) {
    if (scanf("%d %d %d %d", &n, &m, &k, &year_q) != 4) {
        return 0;
    }

    for (int i = 1; i <= n; ++i) head[i] = -1;

    for (int i = 0; i < m; ++i) {
        int u, v;
        int c[MAXDEG + 1];
        scanf("%d %d", &u, &v);
        for (int j = 0; j <= k; ++j) scanf("%d", &c[j]);
        add_edge(u, v, c);
        add_edge(v, u, c);
    }

    for (int i = 1; i <= n; ++i) {
        best[i] = -1.0;
        used[i] = 0;
    }
    best[1] = INF;

    for (int it = 0; it < n; ++it) {
        int u = -1;
        double mx = -1.0;
        for (int i = 1; i <= n; ++i) {
            if (!used[i] && best[i] > mx) {
                mx = best[i];
                u = i;
            }
        }
        if (u == -1) break;
        used[u] = 1;
        if (u == n) break;

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (used[v]) continue;
            double bw = eval_poly(edges[e].coeff, k, year_q);
            double cand = best[u] < bw ? best[u] : bw;
            if (cand > best[v]) best[v] = cand;
        }
    }

    if (best[n] < 0) {
        printf("0\n");
    } else {
        long long ans = (long long)(best[n] + 0.5);
        printf("%lld\n", ans);
    }

    return 0;
}

