using int64 = long long;

struct Edge {
    int to, a, b;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;
    vector<vector<Edge>> g(N);
    vector<tuple<int,int,int,int>> edges; // from, to, a, b
    for (int i = 0; i < M; i++) {
        int u, v, a, b;
        cin >> u >> v >> a >> b;
        u--; v--;
        g[u].push_back({v, a, b});
        g[v].push_back({u, a, b});
        edges.push_back({u, v, a, b});
    }

    auto maxMinBandwidth = [&](int64 year) -> int64 {
        vector<int64> best(N, -1e18);
        best[0] = 1e18;
        priority_queue<pair<int64,int>> pq;
        pq.push({best[0], 0});
        while (!pq.empty()) {
            auto [cap, u] = pq.top(); pq.pop();
            if (cap < best[u]) continue;
            for (auto &e : g[u]) {
                int64 w = (int64)e.a * year + e.b;
                if (w < 0) w = 0;
                int64 newCap = min(cap, w);
                if (newCap > best[e.to]) {
                    best[e.to] = newCap;
                    pq.push({newCap, e.to});
                }
            }
        }
        return best[N-1];
    };

    // Collect candidate years: 0..1e9 and intersections
    vector<int64> candidates = {0, 1000000000};
    for (auto &[u1,v1,a1,b1] : edges) {
        for (auto &[u2,v2,a2,b2] : edges) {
            if (a1 == a2) continue;
            // a1*y + b1 == a2*y + b2 => y = (b2 - b1) / (a1 - a2)
            int64 num = b2 - b1;
            int64 den = a1 - a2;
            if (den == 0) continue;
            // check around the rational point
            for (int64 y : {num/den - 1, num/den, num/den + 1}) {
                if (y >= 0 && y <= 1000000000) candidates.push_back(y);
            }
        }
    }
    // Also zero crossings
    for (auto &[u,v,a,b] : edges) {
        if (a != 0) {
            // a*y + b = 0 => y = -b/a
            int64 y = -b / a;
            for (int64 yy : {y-1, y, y+1}) {
                if (yy >= 0 && yy <= 1000000000) candidates.push_back(yy);
            }
        }
    }

    sort(candidates.begin(), candidates.end());
    candidates.erase(unique(candidates.begin(), candidates.end()), candidates.end());

    int64 ans = 0;
    for (int64 y : candidates) {
        ans = max(ans, maxMinBandwidth(y));
    }
    cout << ans << "\n";

    return 0;
}

