typedef vector<long long> Poly;

Poly add(Poly a, Poly b) {
    int n = max(a.size(), b.size());
    a.resize(n, 0); b.resize(n, 0);
    for (int i = 0; i < n; i++) a[i] += b[i];
    return a;
}

Poly sub(Poly a, Poly b) {
    int n = max(a.size(), b.size());
    a.resize(n, 0); b.resize(n, 0);
    for (int i = 0; i < n; i++) a[i] -= b[i];
    return a;
}

bool positive(Poly a) {
    for (int i = a.size()-1; i >= 0; i--)
        if (a[i] != 0) return a[i] > 0;
    return false;
}

Poly minPoly(Poly a, Poly b) {
    // compare from highest degree
    int n = max(a.size(), b.size());
    a.resize(n,0); b.resize(n,0);
    for (int i = n-1; i >= 0; i--) {
        if (a[i] < b[i]) return a;
        if (a[i] > b[i]) return b;
    }
    return a;
}

#include <bits/stdc++.h>
using namespace std;

struct Poly {
    vector<long long> c; // c[i] = coefficient of x^i
};

static Poly addPoly(const Poly& a, const Poly& b) {
    Poly r;
    r.c.assign(max(a.c.size(), b.c.size()), 0);
    for (size_t i = 0; i < a.c.size(); ++i) r.c[i] += a.c[i];
    for (size_t i = 0; i < b.c.size(); ++i) r.c[i] += b.c[i];
    while (!r.c.empty() && r.c.back() == 0) r.c.pop_back();
    return r;
}

static Poly mulPoly(const Poly& a, const Poly& b) {
    if (a.c.empty() || b.c.empty()) return Poly{};
    Poly r;
    r.c.assign(a.c.size() + b.c.size() - 1, 0);
    for (size_t i = 0; i < a.c.size(); ++i)
        for (size_t j = 0; j < b.c.size(); ++j)
            r.c[i + j] += a.c[i] * b.c[j];
    while (!r.c.empty() && r.c.back() == 0) r.c.pop_back();
    return r;
}

// compare polynomials by value for sufficiently large x:
// higher degree is larger; if equal degree, compare highest differing coefficient.
static int cmpPoly(const Poly& a, const Poly& b) {
    int da = (int)a.c.size() - 1;
    int db = (int)b.c.size() - 1;
    if (da != db) return da < db ? -1 : 1;
    for (int i = da; i >= 0; --i) {
        if (a.c[i] != b.c[i]) return a.c[i] < b.c[i] ? -1 : 1;
    }
    return 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    if (!(cin >> N >> M)) return 0;

    vector<vector<pair<int, Poly>>> g(N + 1);

    for (int i = 0; i < M; ++i) {
        int u, v, d;
        cin >> u >> v >> d;
        Poly p;
        p.c.assign(d + 1, 0);
        for (int j = d; j >= 0; --j) {
            cin >> p.c[j];
        }
        while (!p.c.empty() && p.c.back() == 0) p.c.pop_back();
        g[u].push_back({v, p});
        g[v].push_back({u, p});
    }

    // Maximum spanning tree by polynomial order
    struct Edge {
        int u, v;
        Poly p;
    };

    vector<Edge> edges;
    edges.reserve(M);
    for (int u = 1; u <= N; ++u) {
        for (auto &e : g[u]) {
            int v = e.first;
            if (u < v) edges.push_back({u, v, e.second});
        }
    }

    sort(edges.begin(), edges.end(), [](const Edge& a, const Edge& b) {
        return cmpPoly(a.p, b.p) > 0;
    });

    vector<int> parent(N + 1), rnk(N + 1, 0);
    iota(parent.begin(), parent.end(), 0);

    function<int(int)> findp = [&](int x) {
        return parent[x] == x ? x : parent[x] = findp(parent[x]);
    };

    auto unite = [&](int a, int b) {
        a = findp(a); b = findp(b);
        if (a == b) return false;
        if (rnk[a] < rnk[b]) swap(a, b);
        parent[b] = a;
        if (rnk[a] == rnk[b]) rnk[a]++;
        return true;
    };

    vector<vector<pair<int, Poly>>> tree(N + 1);
    for (auto &e : edges) {
        if (unite(e.u, e.v)) {
            tree[e.u].push_back({e.v, e.p});
            tree[e.v].push_back({e.u, e.p});
        }
    }

    // In maximum spanning tree, bottleneck path between 1 and N is optimal.
    vector<int> par(N + 1, -1);
    vector<Poly> edgeToPar(N + 1);
    queue<int> q;
    q.push(1);
    par[1] = 0;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto &e : tree[u]) {
            int v = e.first;
            if (par[v] == -1) {
                par[v] = u;
                edgeToPar[v] = e.second;
                q.push(v);
            }
        }
    }

    Poly ans = edgeToPar[N];
    int cur = N;
    while (cur != 1) {
        if (cmpPoly(edgeToPar[cur], ans) < 0) ans = edgeToPar[cur];
        cur = par[cur];
    }

    if (ans.c.empty()) {
        cout << 0 << "\n";
    } else {
        int deg = (int)ans.c.size() - 1;
        cout << deg << "\n";
        for (int i = deg; i >= 0; --i) {
            if (i != deg) cout << ' ';
            cout << ans.c[i];
        }
        cout << "\n";
    }

    return 0;
}

