import java.io.*;
import java.util.*;

/*
 * Maximal bandwidth path with edge weights as polynomials in year x.
 *
 * For a fixed x, each edge has value P(x). The bandwidth of a path is the minimum
 * edge value on that path. We need the maximal bandwidth between node 1 and node N.
 *
 * Standard solution for widest path:
 *   dist[v] = maximum possible minimum-edge-value on a path from 1 to v
 *   Use priority queue (max-heap), relax with:
 *      cand = min(dist[u], w(u,v))
 *      dist[v] = max(dist[v], cand)
 *
 * Input format is not explicitly shown in the prompt, so this solution supports
 * a common polynomial-edge format:
 *
 *   N M X
 *   For each of M edges:
 *     u v k a0 a1 ... ak
 *
 * where polynomial is:
 *   a0 + a1*x + ... + ak*x^k
 *
 * Output:
 *   maximal bandwidth value for year X
 *
 * All computations use long. If input values are larger, BigInteger would be needed,
 * but competitive-programming versions of this problem typically fit in long.
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int to;
        long w;
        Edge(int to, long w) {
            this.to = to;
            this.w = w;
        }
    }

    static class State {
        int v;
        long val;
        State(int v, long val) {
            this.v = v;
            this.val = val;
        }
    }

    static long evalPoly(long[] a, long x) {
        // Horner
        long res = 0;
        for (int i = a.length - 1; i >= 0; i--) {
            res = res * x + a[i];
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        int m = fs.nextInt();
        long x = fs.nextLong();

        List<Edge>[] g = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < m; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            int k = fs.nextInt();
            long[] a = new long[k + 1];
            for (int j = 0; j <= k; j++) a[j] = fs.nextLong();
            long w = evalPoly(a, x);
            g[u].add(new Edge(v, w));
            g[v].add(new Edge(u, w));
        }

        long[] best = new long[n + 1];
        Arrays.fill(best, Long.MIN_VALUE);
        best[1] = Long.MAX_VALUE;

        PriorityQueue<State> pq = new PriorityQueue<>((p, q) -> Long.compare(q.val, p.val));
        pq.add(new State(1, best[1]));

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            if (cur.val != best[cur.v]) continue;
            if (cur.v == n) break;

            for (Edge e : g[cur.v]) {
                long cand = Math.min(cur.val, e.w);
                if (cand > best[e.to]) {
                    best[e.to] = cand;
                    pq.add(new State(e.to, cand));
                }
            }
        }

        System.out.println(best[n] == Long.MIN_VALUE ? 0 : best[n]);
    }
}
